    const num_rows = board.len;

    // Determine number of columns from the first row
    // Cell c in row r is at board[r][r + c * 2]
    // Number of cells in row 0: (len(board[0]) + 1) / 2
    const num_cols = (board[0].len + 1) / 2;

    if (num_cols == 0) return '.';

    // Helper to get cell value
